toolCall.argumentsJson:
{"CommandLine":"Get-WinEvent -FilterHashtable @{LogName='Microsoft-Windows-Kernel-PnP/Configuration'} -MaxEvents 15 -ErrorAction SilentlyContinue | Select-Object TimeCreated, Id, Message | Format-List
Get-PnpDevice | Where-Object { $_.InstanceId -match "Z41220090388172" } | ForEach-Object {
    $dev = $_
    $props = Get-PnpDeviceProperty -InstanceId $dev.InstanceId -ErrorAction SilentlyContinue
    $lastConn = ($props | Where-Object { $_.KeyName -match "LastConnected|LastArrival" }).Data
    Write-Host "Device: $($dev.InstanceId) | Status: $($dev.Status) | Last: $lastConn"
}","WaitMsBeforeAsync":6000,"toolSummary":"Check last connected timestamp of box Z41220090388172 in PnP"}
